if(a==='book-workshop-service'){const workshop=state.items.find(x=>x.slug===b.dataset.workshop);const service=workshop?.services?.find(x=>String(x.id)===b.dataset.service);if(!workshop||!service)return;state.bookingItem={kind:'workshop',workshop,service};return go('booking')}
if(a==='book-rental'){const item=state.items.find(x=>String(x.id)===b.dataset.id);if(!item)return;state.bookingItem={kind:'rental',item};return go('booking')}
if(a==='book-service'){const center=state.selectedServiceCenter?.slug===b.dataset.center?state.selectedServiceCenter:state.items.find(x=>x.slug===b.dataset.center);const service=center?.services?.find(x=>String(x.id)===b.dataset.service);if(!center||!service)return;state.bookingItem={kind:'service',center,service};return go('booking')}
if(a==='logout'){try{await api('/api/mobile/logout',{method:'POST'})}catch{}state.token='';state.user=null;localStorage.removeItem('motohub_mobile_token');return go('account')}
