const sf=document.querySelector('#search-form');if(sf)sf.addEventListener('submit',e=>{e.preventDefault();state.search=new FormData(sf).get('q').toString().trim();loadCatalog()});const serviceFilter=document.querySelector('#service-filter-form');if(serviceFilter)serviceFilter.addEventListener('submit',e=>{e.preventDefault();const d=Object.fromEntries(new FormData(serviceFilter).entries());state.servicesFilters={city:(d.city||'').trim(),service:(d.service||'').trim(),verified:d.verified==='1'};loadCatalog()});
