async function loadPassport(id){if(!id)return;state.page='passport';state.passportData=null;state.passportError='';state.passportLoading=true;render();try{state.passportData=await api('/api/mobile/motorcycles/'+encodeURIComponent(id)+'/passport')}catch(e){state.passportError=e.message||'პასპორტის ჩატვირთვა ვერ მოხერხდა.'}finally{state.passportLoading=false;if(state.page==='passport')render()}}
